using Documents.Api.Data;using Documents.Api.Models;using Microsoft.EntityFrameworkCore;
namespace Documents.Api.Services;
public sealed class DocumentService(DocumentsDbContext db){public async Task<TrackedDocument> TransitionAsync(int id,string status,string notes,int userId,bool reviewer,CancellationToken ct=default){await using var tx=await db.Database.BeginTransactionAsync(ct);var d=await db.Documents.Include(x=>x.Events).SingleOrDefaultAsync(x=>x.Id==id,ct)??throw new KeyNotFoundException();var allowed=d.Status switch{Statuses.Draft=>new[]{Statuses.Submitted},Statuses.Submitted=>new[]{Statuses.InReview},Statuses.InReview=>new[]{Statuses.Approved,Statuses.Rejected},Statuses.Approved or Statuses.Rejected=>new[]{Statuses.Archived},_=>[]};if(!allowed.Contains(status))throw new InvalidOperationException($"Cannot change {d.Status} to {status}.");if((status is Statuses.InReview or Statuses.Approved or Statuses.Rejected or Statuses.Archived)&&!reviewer)throw new UnauthorizedAccessException();var previous=d.Status;d.Status=status;d.UpdatedAt=DateTime.UtcNow;d.Events.Add(new DocumentEvent{FromStatus=previous,ToStatus=status,Notes=notes.Trim(),PerformedById=userId});await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return d;}}
